<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Random Hex Generator','description'=>'Generate random hexadecimal values for development and design.','url'=>'https://smarttoolz.in/tools/random-hex-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Random Hex Generator</h1><p>Generate random hexadecimal strings.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Length<input id="n" type="number" min="1" max="128" value="16"></label><button id="go" class="tool-btn">Generate</button><textarea id="o" rows="10" readonly></textarea></div></section></main><script>go.onclick=()=>{let n=Math.min(128,Math.max(1,+document.getElementById('n').value||16));let a=new Uint8Array(n);crypto.getRandomValues(a);o.value=[...a].map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,n)};go.click()</script><?php smarttoolz_tool_page_end(); ?>